Функция в цикле с ограничением числа попыток отправляет запрос; при статусе 429 читает заголовок Retry-After, ждёт указанное число секунд и повторяет запрос; при другом статусе возвращает ответ. Пример:

import time
import requests

def get_with_retry(url, headers=None, max_attempts=5):
    for _ in range(max_attempts):
        response = requests.get(url, headers=headers, timeout=30)
        if response.status_code != 429:
            return response
        time.sleep(int(response.headers.get("Retry-After", "1")))
    return response
